const checkout = process.cwd();
const cli = join(checkout, 'src/server/cli.ts');
let stage = 'empty-database safety check';
let brokenCheckout: string | undefined;
const migrationCliExits: number[] = [];

function runMigrate(expected: number, cwd = checkout) {
  migrationCliExits.push(expected);
  const result = spawnSync(process.execPath, [cli, 'migrate'], { cwd, env: process.env, encoding: 'utf8', timeout: 45_000, maxBuffer: 512_000 });
  assert.equal(result.status, expected, `${stage}: migration CLI exit status`);
  for (const secret of [config.authSecret, config.bootstrapToken, config.databaseUrl]) {
    assert.ok(!(result.stdout + result.stderr).includes(secret), 'Migration output must not expose configuration secrets.');
  }
  return result.stdout + result.stderr;
}

async function history() {
  return (await pool.query<{ version: string; checksum: string }>('SELECT version, checksum FROM schema_version ORDER BY version')).rows;
}

async function schemaSnapshot() {
  const [columns, constraints, indexes] = await Promise.all([
    pool.query(`SELECT table_name, column_name, data_type, is_nullable, column_default
      FROM information_schema.columns WHERE table_schema = 'public' ORDER BY table_name, ordinal_position`),
    pool.query(`SELECT t.relname AS table_name, c.conname AS name, pg_get_constraintdef(c.oid) AS definition
      FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace n ON n.oid = t.relnamespace
      WHERE n.nspname = 'public' ORDER BY t.relname, c.conname`),
    pool.query("SELECT tablename, indexname, indexdef FROM pg_indexes WHERE schemaname = 'public' ORDER BY tablename, indexname"),
  ]);
  return { columns: columns.rows, constraints: constraints.rows, indexes: indexes.rows };
}

// Owner decision 2026-10-18: 0064 drops every Meta table and deletes Google Ads rows. Snapshots taken before it
// skip the dropped tables once they are gone; pre64 applies the same projection to both sides of an older comparison,
// leaving out the rows the 0064 stage seeds (its surviving Search Console grant), which that stage asserts exactly.
const metaTables64=['meta_app_registration','meta_connection','meta_oauth_flow','meta_deletion_request','meta_import','meta_import_page','meta_campaign_inventory','meta_campaign_inventory_page'];
const removed64=new Set<string>(),seeded64=new Set<unknown>(),present=(tables:readonly string[])=>tables.filter(table=>!removed64.has(table));
function pre64<T extends Record<string,unknown>>(snapshot:T):T{return Object.fromEntries(Object.entries(snapshot).filter(([table])=>!metaTables64.includes(table))
  .map(([table,rows])=>[table,(rows as Record<string,unknown>[]).filter(row=>!seeded64.has(row.id)).map(row=>{if(table!=='google_connection')return row;const {login_customer_id,...kept}=row;return kept;})])) as T;}

// Owner decision D1 (P30): 0065 adds six nullable click-ID columns to event. Snapshots taken before it compare through pre65,
// which projects exactly those columns out of current event rows; the 0065 stage asserts them exactly.
const clickIdColumns65=['gclid','fbclid','msclkid','ttclid','li_fat_id','twclid'];
function pre65<T extends Record<string,unknown>>(snapshot:T):T{return Object.fromEntries(Object.entries(snapshot).map(([table,rows])=>[table,table!=='event'?rows:
  (rows as Record<string,unknown>[]).map(row=>Object.fromEntries(Object.entries(row).filter(([column])=>!clickIdColumns65.includes(column))))])) as T;}

// 0070 adds the nullable "user".closed_at column. Row helpers project it out of user rows (as they already project later
// project columns), so snapshots taken before 0070 still compare exactly; the 0070 stage asserts every account stays open.
const fixtureTables = ['installation', 'user', 'account', 'session', 'workspace', 'membership', 'project', 'event'] as const;
async function records() {
  const snapshot: Record<string, Record<string, unknown>[]> = {};
  for (const table of fixtureTables) snapshot[table] = (await pool.query<{ data: Record<string, unknown> }>(`SELECT row_to_json(t) AS data FROM "${table}" t`)).rows.map((row) => row.data);
  return snapshot;
}

